//! Vectors for `tree_sizes`, generated by `scripts/cpp_vectors/frame_tree_sizes_vectors.cpp`.

use std::collections::HashMap;

use fp_core::code::code::Code;
use fp_core::iop::context::{tree_sizes, OracleNotice};
use fp_core::iop::relation::{Codes, OracleShape};

const VECTORS: &str = include_str!("../../fixtures/frame_tree_sizes_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn codes() -> Codes {
    Codes {
        base: vec![Code { log_n: 8, ell: 8, r: 4 }],
        mask: vec![Code { log_n: 6, ell: 4, r: 2 }],
    }
}

fn notice(
    name: &str,
    code: u32,
    mask_code: u32,
    main_rows: usize,
    mask_rows: usize,
    answers: u32,
    leaf_class: u32,
) -> OracleNotice {
    OracleNotice {
        shape: OracleShape {
            name: String::from(name),
            code,
            main_rows,
            main_deg: 1,
            mask_rows,
            mask_code,
            answers,
        },
        leaf_class,
    }
}

#[test]
fn tree_sizes_match_the_cpp_reference() {
    let c = codes();
    let cases: Vec<(&str, Vec<OracleNotice>)> = vec![
        ("single", vec![notice("a", 0, 0, 64, 0, 1, 0)]),
        ("two_share", vec![notice("a", 0, 0, 64, 0, 1, 0), notice("b", 0, 0, 32, 0, 1, 0)]),
        ("two_classes", vec![notice("a", 0, 0, 64, 0, 1, 0), notice("b", 0, 0, 32, 0, 1, 1)]),
        ("mask_only", vec![notice("a", 0, 0, 0, 8, 1, 0)]),
        ("mixed", vec![notice("a", 0, 0, 64, 0, 1, 0), notice("b", 0, 0, 0, 8, 1, 0)]),
        ("one_list_first", vec![notice("a", 0, 0, 64, 0, 0, 0), notice("b", 0, 0, 32, 0, 1, 0)]),
        ("one_list_twice", vec![notice("a", 0, 0, 64, 0, 0, 0), notice("b", 0, 0, 32, 0, 0, 0)]),
        ("mask_one_list", vec![notice("a", 0, 0, 0, 8, 0, 0)]),
    ];
    let mut lines = VECTORS.lines();
    let mut last = 0u64;
    for (name, sent) in cases {
        let head = fields(lines.next().unwrap());
        assert_eq!(head["name"], name);
        let sizes = tree_sizes(&c, &sent, &mut last);
        assert_eq!(head["count"], sizes.len().to_string(), "{}: count", name);
        for t in &sizes {
            let line = lines.next().unwrap();
            let tv = fields(line);
            assert_eq!(tv["name"], name);
            assert_eq!(tv["log_n"], t.log_n.to_string(), "{}: log_n", name);
            assert_eq!(tv["leaf_bytes"], t.leaf_bytes.to_string(), "{}: leaf_bytes", name);
            assert_eq!(tv["one_list"], (t.one_list.yes as u8).to_string(), "{}: one_list", name);
            assert_eq!(tv["number"], t.one_list.number.to_string(), "{}: number", name);
            // The name holds spaces, so it is not one `fields()` token.
            let where_ = line.split_once("where=").unwrap().1;
            assert_eq!(where_, t.name.as_str(), "{}: tree name", name);
        }
    }
    assert!(lines.next().is_none(), "extra vector lines");
}
